package in.malabartrails;
import org.springframework.context.annotation.*;import org.springframework.security.config.annotation.web.builders.HttpSecurity;import org.springframework.security.web.SecurityFilterChain;import org.springframework.web.cors.*;import java.util.*;
@Configuration
public class SecurityConfig {
 @Bean SecurityFilterChain filterChain(HttpSecurity http,AuthService auth,CorsConfigurationSource cors)throws Exception{return http.csrf(c->c.disable()).cors(c->c.configurationSource(cors)).addFilterBefore(auth,org.springframework.security.web.authentication.UsernamePasswordAuthenticationFilter.class).authorizeHttpRequests(a->a.requestMatchers(org.springframework.http.HttpMethod.OPTIONS,"/**").permitAll().requestMatchers("/auth/login","/auth/logout","/packages/**","/destinations/**","/enquiries","/actuator/health","/swagger-ui/**","/v3/api-docs/**").permitAll().requestMatchers("/admin/staff/**","/admin/packages/**").hasAnyRole("ADMIN","EDITOR").requestMatchers("/admin/enquiries/**","/admin/dashboard").hasAnyRole("ADMIN","EDITOR","CONSULTANT").anyRequest().authenticated()).build();}
 @Bean CorsConfigurationSource cors(@org.springframework.beans.factory.annotation.Value("${app.frontend-origin:http://localhost:3000}") String origins){CorsConfiguration c=new CorsConfiguration();c.setAllowedOrigins(Arrays.stream(origins.split(",")).map(String::trim).filter(s->!s.isEmpty()).toList());c.setAllowedMethods(List.of("GET","POST","PUT","PATCH","DELETE","OPTIONS"));c.setAllowedHeaders(List.of("Content-Type","Idempotency-Key","Authorization","X-Requested-With"));c.setAllowCredentials(true);UrlBasedCorsConfigurationSource s=new UrlBasedCorsConfigurationSource();s.registerCorsConfiguration("/**",c);return s;}
 @Bean org.springframework.security.crypto.password.PasswordEncoder passwordEncoder(){return new org.springframework.security.crypto.bcrypt.BCryptPasswordEncoder();}
}
